WITH with_windows AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY status_bits, id) AS event_seq, SUM(status_bits) OVER (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_status_bits, FIRST_VALUE(temp_c) IGNORE NULLS OVER (ORDER BY humidity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_temp_c FROM device_readings) SELECT device_code, STDDEV_SAMP(humidity) AS humidity_stddev, MIN(reading_ts) AS started_at, ROUND(AVG(temp_c), 2) AS avg_temp_c, COUNT_IF(device_code = 'DV-01') AS dv_01_events, PERCENTILE_APPROX(temp_c, ARRAY(0.25, 0.5, 0.75)) AS temp_c_quartiles, PERCENTILE_APPROX(pressure, 0.95) AS pressure_p95 FROM with_windows GROUP BY 1 ORDER BY dv_01_events NULLS FIRST;
